  "headline": "Linezolid is not on FDA's shortage list; supply traces to a plant with multiple VAI inspections",
  "headline_cites": ["D3", "E7", "E3", "E4", "E5", "E6"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include linezolid as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "The product used at both Corvale sites carries NDC 67877041920 and is labeled by Ascend Laboratories, LLC.",
      "cites": ["E1", "E2"]
    },
    {
      "text": "The SPL set ID 7402aa01-50de-46c8-a341-d30da5b32b1c identifies Alkem Laboratories Limited (FEI 3006370524) as the registered manufacturing plant.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspection records for that plant show VAI classifications in 2011-12-09, 2013-10-25, 2016-09-29, and 2018-03-27.",
      "cites": ["E3", "E4", "E5", "E6"]
    },
    {
      "text": "The most recent inspection on record ended 2018-03-27 with a VAI classification.",
      "cites": ["E6"]
    },
    {
      "text": "Corvale East has 5.3 days of 600 mg tablets on hand while Corvale General has 24 days.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The ranked transfer option moves 127 tablets from Corvale General to Corvale East, leaving the sender with 16 days and the receiver with 14 days.",
      "cites": ["D4"]
    }
  ]
}
